from pathlib import Path
root=Path('/mnt/data/p23')

# Phase 23 migration
mig23=root/'supabase/migrations/20260903000008_stripe_webhook_event_lifecycle_atomic.sql'
mig23.write_text('''-- CALQULUS PMS — Phase 23: Stripe webhook claim/complete lifecycle\n-- Do not mark a Stripe event processed before its financial side effects succeed.\n\nALTER TABLE public.stripe_processed_events\n  ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'completed'\n    CHECK (status IN ('processing','completed','failed'));\nALTER TABLE public.stripe_processed_events\n  ADD COLUMN IF NOT EXISTS attempt_count integer NOT NULL DEFAULT 0;\nALTER TABLE public.stripe_processed_events\n  ADD COLUMN IF NOT EXISTS claimed_at timestamptz;\nALTER TABLE public.stripe_processed_events\n  ADD COLUMN IF NOT EXISTS completed_at timestamptz;\nALTER TABLE public.stripe_processed_events\n  ADD COLUMN IF NOT EXISTS last_error text;\n\nCREATE INDEX IF NOT EXISTS idx_stripe_processed_events_status_claimed\n  ON public.stripe_processed_events(status, claimed_at);\n\n-- Atomically claim an event. A completed event is a no-op. A fresh processing\n-- claim is protected for 10 minutes; stale claims can be safely retried.\nCREATE OR REPLACE FUNCTION public.claim_stripe_event_atomic(\n  p_event_id text,\n  p_event_type text\n)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  v_event record;\n  v_claimed boolean := false;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    RAISE EXCEPTION 'Unauthorized Stripe event claim' USING ERRCODE='42501';\n  END IF;\n  IF p_event_id IS NULL OR btrim(p_event_id) = '' OR p_event_type IS NULL OR btrim(p_event_type) = '' THEN\n    RAISE EXCEPTION 'Invalid Stripe event identity' USING ERRCODE='22023';\n  END IF;\n\n  SELECT * INTO v_event\n  FROM public.stripe_processed_events\n  WHERE event_id = btrim(p_event_id)\n  FOR UPDATE;\n\n  IF v_event.event_id IS NULL THEN\n    INSERT INTO public.stripe_processed_events (event_id, event_type, status, attempt_count, claimed_at, last_error)\n    VALUES (btrim(p_event_id), btrim(p_event_type), 'processing', 1, now(), NULL);\n    RETURN jsonb_build_object('success',true,'should_process',true,'status','processing','attempt_count',1);\n  END IF;\n\n  IF v_event.event_type IS DISTINCT FROM btrim(p_event_type) THEN\n    RAISE EXCEPTION 'Stripe event type mismatch for event %', p_event_id USING ERRCODE='23505';\n  END IF;\n\n  IF v_event.status = 'completed' THEN\n    RETURN jsonb_build_object('success',true,'should_process',false,'status','completed','attempt_count',v_event.attempt_count);\n  END IF;\n\n  IF v_event.status = 'processing'\n     AND v_event.claimed_at IS NOT NULL\n     AND v_event.claimed_at > now() - interval '10 minutes' THEN\n    RETURN jsonb_build_object('success',true,'should_process',false,'status','processing','in_progress',true,'attempt_count',v_event.attempt_count);\n  END IF;\n\n  UPDATE public.stripe_processed_events\n  SET status='processing', claimed_at=now(), attempt_count=attempt_count+1, last_error=NULL\n  WHERE event_id=v_event.event_id;\n  v_claimed := true;\n  RETURN jsonb_build_object('success',true,'should_process',v_claimed,'status','processing','attempt_count',v_event.attempt_count+1);\nEND; $$;\n\nCREATE OR REPLACE FUNCTION public.complete_stripe_event_atomic(\n  p_event_id text,\n  p_invoice_id uuid DEFAULT NULL,\n  p_reference text DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_event record;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    RAISE EXCEPTION 'Unauthorized Stripe event completion' USING ERRCODE='42501';\n  END IF;\n  SELECT event_id, status INTO v_event FROM public.stripe_processed_events WHERE event_id=btrim(p_event_id) FOR UPDATE;\n  IF v_event.event_id IS NULL THEN RAISE EXCEPTION 'Stripe event claim not found' USING ERRCODE='P0002'; END IF;\n  IF v_event.status = 'completed' THEN\n    RETURN jsonb_build_object('success',true,'idempotent',true,'status','completed');\n  END IF;\n  UPDATE public.stripe_processed_events\n  SET status='completed', invoice_id=COALESCE(p_invoice_id, invoice_id), reference=COALESCE(p_reference, reference), completed_at=now(), processed_at=now(), last_error=NULL\n  WHERE event_id=v_event.event_id;\n  RETURN jsonb_build_object('success',true,'idempotent',false,'status','completed');\nEND; $$;\n\nCREATE OR REPLACE FUNCTION public.fail_stripe_event_atomic(\n  p_event_id text,\n  p_error text\n)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_event record;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    RAISE EXCEPTION 'Unauthorized Stripe event failure' USING ERRCODE='42501';\n  END IF;\n  SELECT event_id, status INTO v_event FROM public.stripe_processed_events WHERE event_id=btrim(p_event_id) FOR UPDATE;\n  IF v_event.event_id IS NULL THEN RAISE EXCEPTION 'Stripe event claim not found' USING ERRCODE='P0002'; END IF;\n  IF v_event.status = 'completed' THEN\n    RETURN jsonb_build_object('success',true,'idempotent',true,'status','completed');\n  END IF;\n  UPDATE public.stripe_processed_events\n  SET status='failed', last_error=left(coalesce(p_error,'Unknown Stripe webhook failure'),2000), claimed_at=NULL, processed_at=now()\n  WHERE event_id=v_event.event_id;\n  RETURN jsonb_build_object('success',true,'idempotent',false,'status','failed');\nEND; $$;\n\nREVOKE ALL ON FUNCTION public.claim_stripe_event_atomic(text,text) FROM PUBLIC, anon, authenticated;\nREVOKE ALL ON FUNCTION public.complete_stripe_event_atomic(text,uuid,text) FROM PUBLIC, anon, authenticated;\nREVOKE ALL ON FUNCTION public.fail_stripe_event_atomic(text,text) FROM PUBLIC, anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.claim_stripe_event_atomic(text,text) TO service_role;\nGRANT EXECUTE ON FUNCTION public.complete_stripe_event_atomic(text,uuid,text) TO service_role;\nGRANT EXECUTE ON FUNCTION public.fail_stripe_event_atomic(text,text) TO service_role;\n''')

# Phase 24 migration
mig24=root/'supabase/migrations/20260903000009_payment_failure_atomic.sql'
mig24.write_text('''-- CALQULUS PMS — Phase 24: centralize terminal payment-failure transitions\n-- Provider callbacks use a service-role-only RPC instead of ad-hoc UPDATEs.\n\nCREATE OR REPLACE FUNCTION public.mark_payment_transaction_failed_atomic(\n  p_transaction_id uuid,\n  p_failure_reason text\n)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_tx record;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    RAISE EXCEPTION 'Unauthorized payment failure transition' USING ERRCODE='42501';\n  END IF;\n  SELECT id, status INTO v_tx\n  FROM public.payment_transactions\n  WHERE id=p_transaction_id\n  FOR UPDATE;\n  IF v_tx.id IS NULL THEN\n    RAISE EXCEPTION 'Payment transaction not found' USING ERRCODE='P0002';\n  END IF;\n  IF v_tx.status = 'completed' THEN\n    RAISE EXCEPTION 'Completed payment cannot be marked failed' USING ERRCODE='55000';\n  END IF;\n  IF v_tx.status = 'failed' THEN\n    RETURN jsonb_build_object('success',true,'idempotent',true,'transaction_id',v_tx.id,'status','failed');\n  END IF;\n  UPDATE public.payment_transactions\n  SET status='failed', failure_reason=left(coalesce(nullif(btrim(p_failure_reason),''),'Payment failed'),500), updated_at=now()\n  WHERE id=v_tx.id;\n  RETURN jsonb_build_object('success',true,'idempotent',false,'transaction_id',v_tx.id,'status','failed');\nEND; $$;\n\nREVOKE ALL ON FUNCTION public.mark_payment_transaction_failed_atomic(uuid,text) FROM PUBLIC, anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.mark_payment_transaction_failed_atomic(uuid,text) TO service_role;\n''')

stripe=root/'supabase/functions/stripe-webhook/index.ts'
s=stripe.read_text()
start=s.index('  // ── Idempotency ──────────────────────────────────────────────────────')
end=s.index('  // ── Event handling ───────────────────────────────────────────────────', start)
new='''  // ── Idempotency claim ────────────────────────────────────────────────\n  // Claim before side effects, but only mark completed AFTER every side effect\n  // succeeds. Failed/stale claims are retryable instead of permanently stuck.\n  try {\n    const { data: claim, error: claimErr } = await supabase.rpc("claim_stripe_event_atomic", {\n      p_event_id: event.id,\n      p_event_type: event.type,\n    });\n    if (claimErr) throw new Error(`Stripe event claim failed: ${claimErr.message}`);\n    if (!claim?.success || claim.should_process !== true) {\n      log("Stripe event skipped", { eventId: event.id, status: claim?.status });\n      return new Response("ok", { status: 200 });\n    }\n  } catch (err) {\n    log("Stripe event claim unavailable — refusing side effects", { error: String(err), eventId: event.id });\n    return new Response("Webhook temporarily unavailable", { status: 500 });\n  }\n\n'''
s=s[:start]+new+s[end:]
# replace completion update blocks (three variants) with RPCs
s=s.replace('''          await supabase\n            .from("stripe_processed_events")\n            .update({ invoice_id: invoiceId, reference })\n            .eq("event_id", event.id);''','''          const completed = await supabase.rpc("complete_stripe_event_atomic", {\n            p_event_id: event.id, p_invoice_id: invoiceId, p_reference: reference,\n          });\n          if (completed.error) throw new Error(`Stripe event completion: ${completed.error.message}`);''')
s=s.replace('''        await supabase\n          .from("stripe_processed_events")\n          .update({ invoice_id: invoiceId, reference: paymentReference })\n          .eq("event_id", event.id);''','''        const completed = await supabase.rpc("complete_stripe_event_atomic", {\n          p_event_id: event.id, p_invoice_id: invoiceId, p_reference: paymentReference,\n        });\n        if (completed.error) throw new Error(`Stripe event completion: ${completed.error.message}`);''')
# insert completion before return, and failure state in catch
needle='''    return new Response("ok", { status: 200 });\n\n  } catch (err) {'''
replacement='''    const completed = await supabase.rpc("complete_stripe_event_atomic", { p_event_id: event.id });\n    if (completed.error) throw new Error(`Stripe event completion: ${completed.error.message}`);\n    return new Response("ok", { status: 200 });\n\n  } catch (err) {'''
if needle not in s: raise SystemExit('stripe return needle missing')
s=s.replace(needle,replacement,1)
old='''    await recordWebhookFailure(supabase, "stripe", event.id, event, err);\n    return new Response("ok", { status: 200 });'''
new='''    await recordWebhookFailure(supabase, "stripe", event.id, event, err);\n    try {\n      await supabase.rpc("fail_stripe_event_atomic", {\n        p_event_id: event.id,\n        p_error: err instanceof Error ? err.message : String(err),\n      });\n    } catch (stateErr) {\n      log("Unable to persist Stripe event failure state", { error: String(stateErr), eventId: event.id });\n    }\n    // 500 tells Stripe to retry. The DB claim is marked failed, so a retry can reclaim it.\n    return new Response("Webhook processing failed", { status: 500 });'''
if old not in s: raise SystemExit('stripe catch block missing')
s=s.replace(old,new,1)
stripe.write_text(s)

# Phase 24 caller replacements
for fn in ['supabase/functions/mpesa-callback/index.ts','supabase/functions/verify-mpesa-stk-status/index.ts']:
    p=root/fn; t=p.read_text()
    import re
    t=re.sub(r'''await supabase\.from\(["']payment_transactions["']\)\.update\(\{\s*status:\s*["']failed["'],\s*failure_reason:\s*([^\n}]+)\s*\}\)\.eq\(["']id["'],\s*transaction\.id\);''', r'''await supabase.rpc("mark_payment_transaction_failed_atomic", {\n        p_transaction_id: transaction.id,\n        p_failure_reason: \1,\n      });''', t)
    # multiline object variant in mpesa callback
    t=t.replace('''await supabase.from("payment_transactions").update({\n        status: "failed",\n        failure_reason: "Expired",\n      }).eq("id", transaction.id).eq("status", "pending");''','''await supabase.rpc("mark_payment_transaction_failed_atomic", {\n        p_transaction_id: transaction.id,\n        p_failure_reason: "Expired",\n      });''')
    # verify status multiline exact
    t=t.replace('''await supabase.from('payment_transactions').update({\n              status:         'failed',\n              failure_reason: reason,\n            }).eq('id', transaction.id);''','''await supabase.rpc('mark_payment_transaction_failed_atomic', {\n              p_transaction_id: transaction.id,\n              p_failure_reason: reason,\n            });''')
    p.write_text(t)

