# tests
test23=root/'src/test/stripeEventLifecyclePhase23.test.ts'
test23.write_text('''import { describe, expect, it } from 'vitest';\nimport { readFileSync } from 'node:fs';\n\nconst handler = readFileSync('supabase/functions/stripe-webhook/index.ts', 'utf8');\nconst migration = readFileSync('supabase/migrations/20260903000008_stripe_webhook_event_lifecycle_atomic.sql', 'utf8');\n\ndescribe('Phase 23 Stripe webhook event lifecycle', () => {\n  it('claims before side effects and completes only after them', () => {\n    expect(handler).toContain('claim_stripe_event_atomic');\n    expect(handler).toContain('complete_stripe_event_atomic');\n    expect(handler).toContain('fail_stripe_event_atomic');\n    expect(handler).not.toContain('.from("stripe_processed_events")\\n      .insert');\n    expect(handler).not.toContain('.from("stripe_processed_events")\\n            .update');\n  });\n  it('retries failed processing with HTTP 500', () => {\n    expect(handler).toContain('return new Response("Webhook processing failed", { status: 500 });');\n  });\n  it('uses a stale-claim timeout and service-role-only RPCs', () => {\n    expect(migration).toContain("interval '10 minutes'");\n    expect(migration).toContain("REVOKE ALL ON FUNCTION public.claim_stripe_event_atomic(text,text) FROM PUBLIC, anon, authenticated");\n    expect(migration).toContain("GRANT EXECUTE ON FUNCTION public.complete_stripe_event_atomic(text,uuid,text) TO service_role");\n  });\n});\n''')
test24=root/'src/test/paymentFailureAtomicPhase24.test.ts'
test24.write_text('''import { describe, expect, it } from 'vitest';\nimport { readFileSync } from 'node:fs';\n\nconst mpesa = readFileSync('supabase/functions/mpesa-callback/index.ts', 'utf8');\nconst verify = readFileSync('supabase/functions/verify-mpesa-stk-status/index.ts', 'utf8');\nconst migration = readFileSync('supabase/migrations/20260903000009_payment_failure_atomic.sql', 'utf8');\n\ndescribe('Phase 24 payment failure lifecycle', () => {\n  it('routes provider failure transitions through one atomic boundary', () => {\n    expect(mpesa).toContain('mark_payment_transaction_failed_atomic');\n    expect(verify).toContain('mark_payment_transaction_failed_atomic');\n    expect(mpesa).not.toMatch(/from\\(["']payment_transactions["']\\)[\\s\\S]{0,180}\\.update\\(/);\n    expect(verify).not.toMatch(/from\\(["']payment_transactions["']\\)[\\s\\S]{0,180}\\.update\\(/);\n  });\n  it('rejects failure transitions on completed transactions', () => {\n    expect(migration).toContain("v_tx.status = 'completed'");\n    expect(migration).toContain("Completed payment cannot be marked failed");\n    expect(migration).toContain('FOR UPDATE');\n  });\n});\n''')

# docs
doc=root/'docs/CALQULUS_PHASE23_24_STRIPE_PAYMENT_LIFECYCLE_AUDIT.md'
doc.write_text('''# CALQULUS PMS — Phases 23–24 Audit\n\n## Phase 23 — Stripe webhook event lifecycle\n\n`stripe_processed_events` is now a claim/complete state machine. A webhook is claimed before financial side effects, but it is only marked `completed` after the handler finishes successfully. Concurrent fresh claims are rejected as `processing`; stale claims older than ten minutes can be reclaimed. Failed claims are marked `failed`, recorded in the dead-letter queue, and return HTTP 500 so Stripe can retry. The claim/complete/fail RPCs are service-role-only.\n\n## Phase 24 — Payment failure lifecycle\n\nM-Pesa callback and STK verification no longer mutate `payment_transactions` directly. Terminal failure transitions go through `mark_payment_transaction_failed_atomic`, which locks the row, is idempotent for already-failed transactions, and refuses to turn a completed transaction back into failed.\n\n## Validation\n\n- Static source audits: required atomic boundaries present; direct production failure updates removed from targeted provider callbacks.\n- Migration/function grants audited for service-role-only execution.\n- Full npm lint/test/build/typecheck depend on installed project dependencies; if unavailable in the execution environment they remain explicitly blocked rather than reported as passing.\n''')
